def orderlyQueue(S: str, K: int) -> str:
    if K == 1:
        # We can only rotate the string.
        # Find the lexicographically smallest rotation.
        n = len(S)
        doubled = S + S
        min_str = S
        for i in range(1, n):
            candidate = doubled[i:i+n]
            if candidate < min_str:
                min_str = candidate
        return min_str
    else:
        # If K > 1, we can generate any permutation of the string.
        # Thus, the answer is simply the sorted characters.
        return "".join(sorted(S))
